// Compact LINK trade entry and popup. The reward quote uses
// the same amount-weighted curve and live on-chain inputs as the full funds
// dialog; this component only owns presentation and transaction state.

import { TX_CONFIRMED_EVENT } from '../app/contracts.js';
import { registerComponentPoll } from '../app/component-poll.js';
import {
  donateLink,
  formatLinkDonationMultiplier,
  linkDonationFlipQuote,
  readLinkDonationState,
} from '../app/link-donation.js?rev=link-reward-v1';
import {
  deriveCanSign,
  get,
  getViewedAddress,
  subscribe,
} from '../app/store.js';
import { compactUiError } from '../app/ui-error.js';
import { openPanelPopup, closePanelPopup } from '../app/panel-popups.js';

const TOKEN_WEI = 10n ** 18n;
const POLL_MS = 30_000;
const SLIDER_STEPS = 10_000n;

let _readState = readLinkDonationState;
let _donate = donateLink;

function _address(value) {
  const normalized = String(value || '').trim().toLowerCase();
  return normalized || null;
}

/** Parse a decimal LINK amount without crossing through floating point. */
export function parseLinkDonationAmount(value) {
  const match = /^\s*(\d+)(?:\.(\d{0,18}))?\s*$/.exec(String(value ?? ''));
  if (!match) return null;
  const fraction = String(match[2] || '').padEnd(18, '0');
  try {
    return (BigInt(match[1]) * TOKEN_WEI) + BigInt(fraction || '0');
  } catch (_error) {
    return null;
  }
}

function _amountInput(value) {
  let raw;
  try { raw = BigInt(value ?? 0); } catch (_error) { raw = 0n; }
  if (raw < 0n) raw = 0n;
  const whole = raw / TOKEN_WEI;
  const fraction = String(raw % TOKEN_WEI).padStart(18, '0').replace(/0+$/, '');
  return fraction ? `${whole}.${fraction}` : String(whole);
}

function _valuePercent(multiplier) {
  return multiplier == null ? '—' : `${(multiplier * 100n + TOKEN_WEI / 2n) / TOKEN_WEI}%`;
}

/** Compact token values while retaining useful precision for small LINK quotes. */
export function formatLinkDonationAmount(value) {
  let raw;
  try { raw = BigInt(value ?? 0); } catch (_error) { return '—'; }
  const negative = raw < 0n;
  if (negative) raw = -raw;
  const tiers = [
    [1_000_000_000_000n * TOKEN_WEI, 'T'],
    [1_000_000_000n * TOKEN_WEI, 'B'],
    [1_000_000n * TOKEN_WEI, 'M'],
    [1_000n * TOKEN_WEI, 'K'],
  ];
  const tier = tiers.find(([threshold]) => raw >= threshold);
  const scale = tier?.[0] ?? TOKEN_WEI;
  const suffix = tier?.[1] ?? '';
  const whole = raw / scale;
  const decimals = suffix
    ? (whole >= 100n ? 0 : whole >= 10n ? 1 : 2)
    : (whole >= 100n ? 0 : whole >= 10n ? 1 : whole >= 1n ? 2 : 4);
  const factor = 10n ** BigInt(decimals);
  const rounded = ((raw * factor) + (scale / 2n)) / scale;
  if (raw > 0n && rounded === 0n) return `${negative ? '-' : ''}<0.${'0'.repeat(Math.max(0, decimals - 1))}1`;
  const integer = rounded / factor;
  const fraction = decimals === 0
    ? ''
    : String(rounded % factor).padStart(decimals, '0').replace(/0+$/, '');
  return `${negative ? '-' : ''}${integer.toLocaleString('en-US')}${fraction ? `.${fraction}` : ''}${suffix}`;
}

function _setWriteLock(button, locked, reason = '') {
  if (!button) return;
  button.disabled = Boolean(locked);
  if (locked) {
    button.setAttribute('data-write-locked', '');
    button.setAttribute('data-write-lock-title', reason);
    button.title = reason;
  } else {
    button.removeAttribute('data-write-locked');
    button.removeAttribute('data-write-lock-title');
    button.removeAttribute('title');
  }
}

class AppLinkDonation extends HTMLElement {
  #initialized = false;
  #unsubs = [];
  #poll = null;
  #txListener = null;
  #refreshQueued = false;
  #seq = 0;
  #address = null;
  #state = null;
  #busy = false;
  #amountTouched = false;

  connectedCallback() {
    if (this.#initialized) return;
    this.#initialized = true;
    this.#renderShell();
    this.#wire();
    for (const key of ['connected.address', 'viewing.address']) {
      this.#unsubs.push(subscribe(key, () => this.#onIdentityChange()));
    }
    for (const key of ['ui.mode', 'ui.chainOk']) {
      this.#unsubs.push(subscribe(key, () => this.#render()));
    }
    this.#poll = registerComponentPoll(() => this.#refresh(), POLL_MS);
    if (typeof document !== 'undefined') {
      this.#txListener = () => this.#queueRefresh();
      document.addEventListener?.(TX_CONFIRMED_EVENT, this.#txListener);
    }
    this.#onIdentityChange();
  }

  disconnectedCallback() {
    closePanelPopup('link-trade', { restoreFocus: false });
    for (const unsubscribe of this.#unsubs) {
      try { unsubscribe(); } catch (_error) { /* defensive */ }
    }
    this.#unsubs = [];
    if (typeof this.#poll === 'function') this.#poll();
    if (this.#txListener && typeof document !== 'undefined') {
      document.removeEventListener?.(TX_CONFIRMED_EVENT, this.#txListener);
    }
    this.#poll = null;
    this.#txListener = null;
    this.#refreshQueued = false;
    this.#seq += 1;
    this.#initialized = false;
  }

  #renderShell() {
    this.innerHTML = `
      <button type="button" class="secondary-action link-trade-open" data-bind="link-open"
              aria-haspopup="dialog" aria-expanded="false" aria-controls="panel-link-trade">
        <img src="/symbols/crypto_05_chainlink_blue.svg" alt="" aria-hidden="true">
        <span>TRADE LINK FOR FLIP</span><strong data-bind="link-current-value">— VALUE</strong>
      </button>
      <section class="panel-popup secondary-popup link-trade-popup" id="panel-link-trade" data-panel-popup="link-trade"
               data-bind="link-dialog" hidden role="dialog" aria-modal="true" aria-labelledby="link-trade-title">
        <div class="panel-popup__window">
          <header class="panel-popup__header">
            <h2 id="link-trade-title">TRADE LINK FOR FLIP</h2>
            <button type="button" class="panel-popup__close" data-panel-close aria-label="Close LINK trade">×</button>
          </header>
          <div class="panel-popup__body">
            <div class="link-trade" data-bind="link-shell">
              <div class="link-trade__balance" data-bind="link-balance-wrap">
                <span><img src="/symbols/crypto_05_chainlink_blue.svg" alt="">LINK BALANCE</span>
                <strong><span data-bind="link-balance">—</span> <small>LINK</small></strong>
              </div>
              <label class="link-trade__label" for="link-trade-amount">YOU TRADE</label>
              <div class="link-trade__amount">
                <input id="link-trade-amount" type="text" data-bind="link-amount" inputmode="decimal"
                       autocomplete="off" spellcheck="false" aria-label="LINK to trade">
                <span>LINK</span><button type="button" data-bind="link-max">MAX</button>
              </div>
              <input class="link-trade__slider" type="range" min="0" max="10000" step="1" value="0"
                     data-bind="link-slider" aria-label="Share of LINK balance to trade">
              <div class="link-trade__range"><span>0%</span><output data-bind="link-share">0% of balance</output><span>100%</span></div>
              <div class="link-trade__quote" data-bind="link-quote" data-state="loading" aria-live="polite">
                <div><small>EST. RECEIVE</small><output data-bind="link-quote-reward">— FLIP</output>
                  <span>for <output data-bind="link-quote-input">1 LINK</output></span></div>
                <div><small>AVG. MULTI</small><strong data-bind="link-multiplier">—</strong>
                  <span data-bind="link-average-value">— value</span></div>
              </div>
              <p class="link-trade__note">Your LINK funds game randomness. FLIP value uses the protocol rate. Larger trades can lower the average multiplier; the final reward uses the rate when your transaction lands.</p>
              <p class="link-trade__status" data-bind="link-status" role="status" hidden></p>
              <button type="button" class="link-trade__submit" data-write data-write-locked
                      data-write-lock-title="LINK balance is loading" data-bind="link-donate">
                <b data-bind="link-donate-label">TRADE LINK FOR FLIP</b>
              </button>
              <p class="link-trade__feedback" data-bind="link-feedback" hidden role="status"></p>
            </div>
          </div>
        </div>
      </section>
    `;
    const input = this.querySelector('[data-bind="link-amount"]');
    if (input) input.value = '1';
  }

  #wire() {
    const trigger = this.querySelector('[data-bind="link-open"]');
    trigger?.addEventListener('click', () => {
      openPanelPopup('link-trade', trigger, this.querySelector('[data-bind="link-dialog"]'));
      trigger.setAttribute('aria-expanded', 'true');
      this.#queueRefresh();
    });
    this.querySelector('[data-bind="link-dialog"]')?.addEventListener('app:panel-close', () => {
      trigger?.setAttribute('aria-expanded', 'false');
    });
    this.querySelector('[data-bind="link-donate"]')
      ?.addEventListener('click', () => { void this.#submit(); });
    this.querySelector('[data-bind="link-max"]')
      ?.addEventListener('click', () => this.#setMax());
    const input = this.querySelector('[data-bind="link-amount"]');
    input?.addEventListener('input', () => { this.#amountTouched = true; this.#render(); });
    this.querySelector('[data-bind="link-slider"]')?.addEventListener('input', (event) => {
      if (this.#busy || this.#state?.balanceWei == null) return;
      const steps = Math.max(0, Math.min(Number(SLIDER_STEPS), Math.round(Number(event.target.value) || 0)));
      input.value = _amountInput(this.#state.balanceWei * BigInt(steps) / SLIDER_STEPS);
      this.#amountTouched = true;
      this.#render();
    });
    input?.addEventListener('keydown', (event) => {
      if (event?.key === 'Enter') void this.#submit();
    });
  }

  #onIdentityChange() {
    const next = _address(getViewedAddress());
    if (next !== this.#address) {
      closePanelPopup('link-trade', { restoreFocus: false });
      this.#seq += 1;
      this.#address = next;
      this.#state = null;
      this.#amountTouched = false;
      const input = this.querySelector('[data-bind="link-amount"]');
      if (input) input.value = '1';
      this.#setFeedback('');
    }
    this.#render();
    this.#queueRefresh();
  }

  #queueRefresh() {
    if (!this.#initialized || this.#refreshQueued) return;
    this.#refreshQueued = true;
    queueMicrotask(() => {
      this.#refreshQueued = false;
      if (this.#initialized) void this.#refresh();
    });
  }

  async #refresh() {
    const target = _address(getViewedAddress());
    if (target !== this.#address) {
      this.#address = target;
      this.#state = null;
      this.#seq += 1;
      this.#render();
    }
    if (!target) return;
    const seq = ++this.#seq;
    let snapshot;
    try { snapshot = await _readState({ player: target }); }
    catch (_error) { return; }
    if (seq !== this.#seq || target !== this.#address) return;
    if (!snapshot) {
      this.#state = null;
    } else {
      const normalized = {};
      for (const key of [
        'balanceWei',
        'creditWei',
        'subscriptionBalanceWei',
        'ethPerLinkWei',
        'mintPriceWei',
      ]) {
        try { normalized[key] = snapshot[key] == null ? null : BigInt(snapshot[key]); }
        catch (_error) { normalized[key] = null; }
      }
      this.#state = normalized;
      if (!this.#amountTouched && normalized.balanceWei != null) {
        const input = this.querySelector('[data-bind="link-amount"]');
        if (input) input.value = _amountInput(normalized.balanceWei < TOKEN_WEI ? normalized.balanceWei : TOKEN_WEI);
      }
    }
    this.#render();
  }

  #canWrite() {
    const connected = _address(get('connected.address'));
    return Boolean(
      connected
      && connected === this.#address
      && get('ui.mode') === 'self'
      && deriveCanSign()
    );
  }

  #lockReason() {
    if (this.#busy) return 'Transaction in progress';
    if (!this.#address) return 'Connect a wallet first';
    if (!this.#canWrite()) return 'Open your own wallet on the correct network to trade LINK';
    if (this.#state?.balanceWei == null) return 'LINK balance is loading';
    if (this.#state.balanceWei <= 0n) return 'No LINK is available to trade';
    return '';
  }

  #quote(amount) {
    const pricingReady = this.#state?.subscriptionBalanceWei != null
      && this.#state?.ethPerLinkWei != null
      && this.#state?.mintPriceWei != null;
    if (!pricingReady || amount == null || amount < 0n) return null;
    return linkDonationFlipQuote({
      amountWei: amount,
      subscriptionBalanceWei: this.#state.subscriptionBalanceWei,
      ethPerLinkWei: this.#state.ethPerLinkWei,
      mintPriceWei: this.#state.mintPriceWei,
    });
  }

  #render() {
    const balance = this.querySelector('[data-bind="link-balance"]');
    const balanceWrap = this.querySelector('[data-bind="link-balance-wrap"]');
    if (balance) balance.textContent = this.#state?.balanceWei == null
      ? '—'
      : formatLinkDonationAmount(this.#state.balanceWei);
    if (balanceWrap) {
      const exact = this.#state?.balanceWei == null
        ? ''
        : `${_amountInput(this.#state.balanceWei)} LINK`;
      balanceWrap.title = exact;
      if (exact) balanceWrap.setAttribute('aria-label', `LINK wallet balance: ${exact}`);
      else balanceWrap.removeAttribute('aria-label');
    }

    const input = this.querySelector('[data-bind="link-amount"]');
    const amount = parseLinkDonationAmount(input?.value);
    const quote = this.#quote(amount);
    const current = this.#quote(0n);
    const currentValue = this.querySelector('[data-bind="link-current-value"]');
    if (currentValue) currentValue.textContent = `${_valuePercent(current?.currentMultiplierWei)} VALUE`;
    const averageValue = this.querySelector('[data-bind="link-average-value"]');
    if (averageValue) averageValue.textContent = `${_valuePercent(quote?.averageMultiplierWei)} value`;
    const quoteBox = this.querySelector('[data-bind="link-quote"]');
    const quoteInput = this.querySelector('[data-bind="link-quote-input"]');
    const quoteReward = this.querySelector('[data-bind="link-quote-reward"]');
    const multiplier = this.querySelector('[data-bind="link-multiplier"]');
    const pricingReady = this.#state?.subscriptionBalanceWei != null
      && this.#state?.ethPerLinkWei != null
      && this.#state?.mintPriceWei != null;
    const inputLabel = amount == null ? '— LINK' : `${formatLinkDonationAmount(amount)} LINK`;
    const rewardLabel = quote == null ? '— FLIP' : `${formatLinkDonationAmount(quote.flipWei)} FLIP`;
    if (quoteInput) quoteInput.textContent = inputLabel;
    if (quoteReward) quoteReward.textContent = rewardLabel;
    if (multiplier) {
      multiplier.textContent = quote == null
        ? '—'
        : formatLinkDonationMultiplier(quote.averageMultiplierWei);
    }
    if (quoteBox) {
      quoteBox.dataset.state = this.#state == null
        ? 'loading'
        : pricingReady ? 'ready' : 'unavailable';
      quoteBox.setAttribute('aria-label', quote
        ? `Funding with ${inputLabel} is estimated to receive ${rewardLabel} at an average ${formatLinkDonationMultiplier(quote.averageMultiplierWei)} reward multiplier.`
        : pricingReady
            ? 'Enter a valid LINK funding amount for a FLIP reward quote.'
          : this.#state == null
            ? 'Loading the current LINK funding reward quote.'
            : 'The current LINK funding reward quote is unavailable.');
    }

    const valid = amount != null
      && amount > 0n
      && this.#state?.balanceWei != null
      && amount <= this.#state.balanceWei;
    if (input) {
      if (input.value && !valid) input.setAttribute('aria-invalid', 'true');
      else input.removeAttribute('aria-invalid');
      input.disabled = this.#busy;
    }
    const donate = this.querySelector('[data-bind="link-donate"]');
    const donateLabel = this.querySelector('[data-bind="link-donate-label"]');
    if (donateLabel) donateLabel.textContent = this.#busy ? 'TRADING…' : 'TRADE LINK FOR FLIP';
    const lockReason = this.#lockReason()
      || (!valid ? 'Enter an amount up to your LINK balance' : '')
      || (quote == null ? 'FLIP quote unavailable. Try again shortly.' : '')
      || (quote.flipWei <= 0n ? 'No FLIP reward is available for this trade.' : '');
    _setWriteLock(
      donate,
      Boolean(lockReason),
      lockReason,
    );
    const status = this.querySelector('[data-bind="link-status"]');
    if (status) { status.textContent = lockReason; status.hidden = !lockReason || this.#busy; }
    const max = this.querySelector('[data-bind="link-max"]');
    if (max) max.disabled = this.#busy || !this.#state?.balanceWei;
    const slider = this.querySelector('[data-bind="link-slider"]');
    const balanceWei = this.#state?.balanceWei ?? 0n;
    // Round to the nearest slider step so integer token rounding cannot pull
    // the thumb back a step after every keyboard increment.
    const share = balanceWei > 0n && amount != null
      ? (amount * SLIDER_STEPS + balanceWei / 2n) / balanceWei : 0n;
    const clampedShare = share > SLIDER_STEPS ? SLIDER_STEPS : share;
    const shareLabel = `${Number(clampedShare) / 100}% of balance`;
    if (slider) {
      slider.value = String(clampedShare);
      slider.disabled = this.#busy || balanceWei <= 0n;
      slider.setAttribute('aria-valuetext', `${inputLabel}, ${shareLabel}`);
    }
    const shareNode = this.querySelector('[data-bind="link-share"]');
    if (shareNode) shareNode.textContent = shareLabel;
  }

  #setMax() {
    if (this.#state?.balanceWei == null) return;
    const input = this.querySelector('[data-bind="link-amount"]');
    if (!input) return;
    input.value = _amountInput(this.#state.balanceWei);
    this.#amountTouched = true;
    this.#render();
  }

  #setFeedback(message, { error = false } = {}) {
    const node = this.querySelector('[data-bind="link-feedback"]');
    if (!node) return;
    node.textContent = String(message || '');
    node.hidden = !message;
    if (error) node.setAttribute('data-state', 'error');
    else node.removeAttribute('data-state');
  }

  async #submit() {
    if (this.#busy || !this.#canWrite()) return;
    const input = this.querySelector('[data-bind="link-amount"]');
    const amount = parseLinkDonationAmount(input?.value);
    if (amount == null || amount <= 0n) {
      this.#setFeedback('Enter a LINK amount to trade.', { error: true });
      return;
    }
    if (this.#state?.balanceWei == null || amount > this.#state.balanceWei) {
      this.#setFeedback('Not enough LINK for that trade.', { error: true });
      return;
    }
    const quote = this.#quote(amount);
    if (!quote || quote.flipWei <= 0n) {
      this.#setFeedback('A positive FLIP quote is needed to trade. Try again shortly.', { error: true });
      return;
    }

    const target = this.#address;
    this.#busy = true;
    this.#setFeedback('');
    this.#render();
    try {
      await _donate({ amount });
      if (target !== this.#address) return;
      if (this.#state?.balanceWei != null) this.#state.balanceWei -= amount;
      this.#setFeedback(`${formatLinkDonationAmount(amount)} LINK FUNDED · FLIP CREDITED`);
      this.#queueRefresh();
    } catch (error) {
      if (target === this.#address) {
        this.#setFeedback(
          compactUiError(error, 'LINK funding did not go through.'),
          { error: true },
        );
      }
    } finally {
      this.#busy = false;
      this.#render();
    }
  }
}

if (typeof customElements !== 'undefined' && !customElements.get('app-link-donation')) {
  customElements.define('app-link-donation', AppLinkDonation);
}

/** Test-only dependency seam. */
export function __setLinkDonationWidgetDepsForTest({ read, donate } = {}) {
  if (typeof read === 'function') _readState = read;
  if (typeof donate === 'function') _donate = donate;
}

/** Test-only dependency reset. */
export function __resetLinkDonationWidgetDepsForTest() {
  _readState = readLinkDonationState;
  _donate = donateLink;
}
